<script setup lang="ts">
/**
 * SettingsPage: the installation's `config.json` as a form generated by the server (`GET /api/v1/settings`).
 * Each field holds the stored value; an empty field keeps the built-in default. Saving posts the form's
 * `ActionView` request; the server validates it and refuses a file that changed since it was shown. Saved
 * values apply when Grampus next starts, which the page says until the dashboard is restarted.
 */
import { onMounted, ref } from 'vue';
import type { SettingsV1 } from '../../../src/server/api-types';
import { buildRequest, type FieldIssue, type FormDrafts } from '../api/actions';
import { ApiError, get, request } from '../api/client';
import { announce } from '../announcer';
import ActionForm from '../components/ActionForm.vue';
import ErrorBanner from '../components/ErrorBanner.vue';
import NoticeBox from '../components/NoticeBox.vue';

defineOptions({ name: 'SettingsPage' });

const settings = ref<SettingsV1>();
const loadError = ref('');
const saving = ref(false);
const fieldIssues = ref<FieldIssue[]>([]);
const failure = ref<{ message: string; issues: readonly string[] } | null>(null);
const saved = ref(false);

async function load(): Promise<void> {
  try {
    settings.value = await get<SettingsV1>('/api/v1/settings');
    loadError.value = '';
  } catch (caught) {
    loadError.value = caught instanceof ApiError ? caught.message : String(caught);
  }
}

onMounted(load);

async function save(drafts: FormDrafts): Promise<void> {
  const action = settings.value?.save;
  if (!action || saving.value) return;
  const built = buildRequest(action, drafts);
  if (!built.ok) {
    fieldIssues.value = built.issues;
    return;
  }
  fieldIssues.value = [];
  failure.value = null;
  saved.value = false;
  saving.value = true;
  try {
    await request<unknown>(built.method, built.path, built.body);
    await load();
    saved.value = true;
    announce('Settings saved. Restart the dashboard to apply them.');
  } catch (caught) {
    const error = caught instanceof ApiError ? caught : new ApiError(0, String(caught));
    if (error.unauthorised) return;
    // A stale save changed nothing: show the file as it is now, so the person can edit from there.
    if (error.stale) await load();
    failure.value = { message: error.message, issues: error.issues };
    announce(`Settings were not saved: ${error.message}`);
  } finally {
    saving.value = false;
  }
}
</script>

<template>
  <div class="mx-auto flex max-w-3xl flex-col gap-6">
    <div class="flex flex-col gap-1">
      <h1 class="text-2xl font-semibold text-highlighted">Settings</h1>
      <p v-if="settings?.file" class="text-sm text-muted" data-file>
        Stored in <span class="font-mono break-all">{{ settings.file }}</span>
      </p>
    </div>
    <ErrorBanner
      v-if="loadError"
      :message="loadError"
      title="The settings could not be read"
      retry-label="Try again"
      @retry="load"
    />
    <p v-else-if="!settings" class="text-sm text-muted" role="status">Loading settings…</p>
    <template v-if="settings">
      <NoticeBox v-if="settings.problem" tone="error" title="The settings file has a problem" data-problem>
        {{ settings.problem }} Grampus will not start until it is fixed; saving here replaces it.
      </NoticeBox>
      <NoticeBox v-if="settings.restartRequired" tone="warning" title="Restart to apply" data-restart>
        The saved settings differ from the ones this dashboard started with. Close the dashboard and start it again to
        use them.
      </NoticeBox>
      <NoticeBox v-if="saved" tone="success" title="Settings saved" live="status">
        They apply when Grampus next starts.
      </NoticeBox>
      <NoticeBox v-if="failure" tone="error" title="Settings were not saved" live="alert" data-failure>
        {{ failure.message }}
        <ul v-if="failure.issues.length" class="mt-1 list-disc pl-5">
          <li v-for="issue in failure.issues" :key="issue">{{ issue }}</li>
        </ul>
      </NoticeBox>
      <ActionForm :action="settings.save" :busy="saving" :sending="saving" :issues="fieldIssues" @submit="save" />
    </template>
  </div>
</template>
